bounded_host_request.command:
set -euo pipefail
src=82c02b1e85fa7749ddaa3f50d879ea88795778a3
name=gace-createvdobot-videobot-poll-1
if docker inspect "$name" >/dev/null 2>&1 && test "$(docker inspect -f '{{.State.Running}}' "$name")" = true && docker logs --tail 120 "$name" 2>&1 | grep -q '^CREATOR_DM_POLL_READY=PASS$';then
 echo STK04_ALREADY_READY=PASS
 exit 0
fi
git fetch --no-tags origin feat/assistant-ai-and-sales-core >/dev/null 2>&1 || { echo STK04_FETCH_FAILED; exit 61; }
git cat-file -e "$src^{commit}" || { echo STK04_SOURCE_SHA_UNAVAILABLE; exit 62; }
target="$HOME/.local/share/gace-create-videobot/sticker-poll-$src"
mkdir -p "$target"
chmod 700 "$target"
git archive "$src" | tar -xf - -C "$target"
test -f "$target/src/runtime/main.mjs" && test -f "$target/src/runtime/creatorPollingMain.mjs" || { echo STK04_STAGE_MISSING; exit 63; }
grep -Fq 'COPY --chown=node:node src ./src' "$target/deploy/Dockerfile" || { echo STK04_DOCKERFILE_NOT_FIXED; exit 64; }
tag=create-videobot:stk04-candidate-82c02b1
log="$(mktemp /tmp/stk04-docker-build.XXXXXXXX)"
trap 'rm -f "$log"' EXIT
if ! docker build --no-cache --pull=false --network host -f "$target/deploy/Dockerfile" -t "$tag" "$target" >"$log" 2>&1; then
 echo STK04_DOCKER_BUILD_FAILED
 grep -Ei 'failed|error|unavailable|timeout' "$log" | tail -n 4 | sed -E 's#https?://[^ ]+#URL_REDACTED#g' || true
 exit 65
fi
docker run --rm --network none --pull never --entrypoint /bin/sh "$tag" -c '
test -f /opt/videobot/src/runtime/main.mjs &&
test -f /opt/videobot/src/runtime/creatorPollingMain.mjs &&
test -f /opt/videobot/src/runtime/creatorPollingConsumer.mjs &&
test -f /opt/videobot/src/runtime/creatorMigrate.mjs &&
test -d /opt/videobot/node_modules/pg' >/dev/null || { echo STK04_CANDIDATE_FILES_INACCESSIBLE; exit 66; }
docker run --rm --network none --pull never --entrypoint node "$tag" -e "import('./src/runtime/creatorPollingMain.mjs').then(()=>process.exit(0)).catch(()=>process.exit(1))" >/dev/null || { echo STK04_CANDIDATE_IMPORT_FAILED; exit 67; }
test "$(docker image inspect -f '{{.Config.User}}' "$tag")" = node || { echo STK04_USER_MISMATCH; exit 68; }
echo STK04_IMAGE_SOURCE_AND_IMPORT=PASS
docker inspect "$name" >/dev/null 2>&1 || { echo STK04_CURRENT_CONTAINER_ABSENT; exit 69; }
token="$(docker inspect -f '{{range .Mounts}}{{if eq .Destination "/run/secrets/videobot_telegram_token"}}{{.Source}}{{end}}{{end}}' "$name")"
dbpass="$(docker inspect -f '{{range .Mounts}}{{if eq .Destination "/run/secrets/videobot_db_password"}}{{.Source}}{{end}}{{end}}' "$name")"
test -f "$token" && test -f "$dbpass" && test ! -L "$token" && test ! -L "$dbpass" || { echo STK04_SECRET_MOUNT_INVALID; exit 70; }
uid="$(docker run --rm --network none --pull never --entrypoint id "$tag" -u)"
test "$(stat -c '%u' "$token")" = "$uid" && test "$(stat -c '%u' "$dbpass")" = "$uid" || { echo STK04_SECRET_OWNER_MISMATCH; exit 71; }
docker run --rm --network none --pull never --cap-drop ALL --security-opt no-new-privileges:true --entrypoint /bin/sh \
 --mount "type=bind,source=$token,target=/run/secrets/videobot_telegram_token,readonly" \
 --mount "type=bind,source=$dbpass,target=/run/secrets/videobot_db_password,readonly" \
 "$tag" -c 'test -r /run/secrets/videobot_telegram_token && test -r /run/secrets/videobot_db_password' >/dev/null || { echo STK04_PRIVATE_MOUNT_ACCESS_FAIL; exit 72; }
other="$(docker ps --format '{{.Names}}' | grep -Ei 'create-videobot|createvdobot|videobot-poll|videobot-telegram' | grep -Fxv "$name" || true)"
test -z "$other" || { echo STK04_SECOND_CONSUMER_PRESENT; exit 73; }
pg="$(docker ps --format '{{.Names}}' | grep -Ei '(^|[-_])postgres([-_]|$)' || true)"
test "$(printf '%s\n' "$pg" | sed '/^$/d' | wc -l)" -eq 1 || { echo STK04_POSTGRES_NOT_UNIQUE; exit 74; }
user="$(docker exec "$pg" sh -c 'printf %s "$POSTGRES_USER"')"
net="$(docker inspect -f '{{range $k,$v := .NetworkSettings.Networks}}{{println $k}}{{end}}' "$pg" | sed '/^$/d')"
test -n "$user" && test "$net" = deploy_default || { echo STK04_DB_OWNER_INVALID; exit 75; }
export VIDEOBOT_TELEGRAM_TOKEN_SOURCE="$token" VIDEOBOT_DB_PASSWORD_SOURCE="$dbpass"
export GSERVER_POSTGRES_USER="$user" GSERVER_POSTGRES_NETWORK="$net"
docker compose -p gace-createvdobot -f "$target/deploy/compose.videobot.poll.yaml" config --quiet || { echo STK04_COMPOSE_CONFIG_INVALID; exit 76; }
docker image tag create-videobot:local-poll create-videobot:poll-rollback
docker image tag "$tag" create-videobot:local-poll
docker compose -p gace-createvdobot -f "$target/deploy/compose.videobot.poll.yaml" up -d --no-build --force-recreate videobot-poll >/dev/null 2>&1 || { echo STK04_COMPOSE_RECREATE_FAILED; exit 77; }
sleep 9
test "$(docker inspect -f '{{.State.Running}}' "$name" 2>/dev/null)" = true || { echo STK04_NOT_RUNNING; exit 78; }
docker logs --tail 100 "$name" 2>&1 | grep -q '^CREATOR_DM_POLL_READY=PASS$' || { echo STK04_READY_NOT_VERIFIED; exit 79; }
echo STK04_DM_READY=PASS
docker logs --tail 100 "$name" 2>&1 | grep -E '^CREATOR_(DM|GATE|POLL)_' | tail -n 8 || true
